<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import http from '@/api/http'

const router = useRouter()
const loading = ref(true)
const data = ref({ cinema: {}, showings: [], orders: [] })
const statusText = { APPROVED: '已认证', PENDING: '认证审核中', REJECTED: '认证未通过' }
const statusType = { APPROVED: 'success', PENDING: 'warning', REJECTED: 'danger' }
const pendingShows = computed(() => data.value.showings?.filter(item => item.approvalStatus === 'PENDING') || [])
async function load() { loading.value = true; try { const { data: res } = await http.get('/cinema/dashboard'); data.value = res } finally { loading.value = false } }
onMounted(load)
</script>
