    <div class="admin-grid-stats mt-24"><div class="stat-card"><div class="flex-between"><span class="label">今日票房</span><span class="stat-icon"><el-icon><TrendCharts /></el-icon></span></div><div class="value">¥{{ Number(data.todayRevenue || 0).toFixed(2) }}</div><small>本影院实时收入</small></div><div class="stat-card"><div class="flex-between"><span class="label">今日场次</span><span class="stat-icon"><el-icon><Calendar /></el-icon></span></div><div class="value">{{ data.showingCount || 0 }}</div><small>已审批待放映</small></div><div class="stat-card"><div class="flex-between"><span class="label">影厅数量</span><span class="stat-icon"><el-icon><OfficeBuilding /></el-icon></span></div><div class="value">{{ data.roomCount || 0 }}</div><small>可用放映空间</small></div><div class="stat-card"><div class="flex-between"><span class="label">待取票订单</span><span class="stat-icon"><el-icon><Tickets /></el-icon></span></div><div class="value">{{ data.paidOrderCount || 0 }}</div><small>需现场核销</small></div></div>
    <div class="cinema-dash-grid mt-24"><div class="table-card"><div class="table-toolbar"><h3>近期排片</h3><router-link to="/cinema-admin/showings" class="section-more">管理排片 <el-icon><ArrowRight /></el-icon></router-link></div><el-table :data="data.showings" size="small"><el-table-column label="电影" min-width="125"><template #default="{row}"><div class="mini-movie"><img :src="row.poster" /><div><b>{{ row.movieTitle }}</b><small>{{ row.roomName }}</small></div></div></template></el-table-column><el-table-column prop="startTime" label="放映时间" width="135" /><el-table-column label="审批" width="80"><template #default="{row}"><el-tag size="small" :type="row.approvalStatus==='APPROVED'?'success':row.approvalStatus==='PENDING'?'warning':'danger'" round>{{ row.approvalStatus==='APPROVED'?'已通过':row.approvalStatus==='PENDING'?'待审批':'已驳回' }}</el-tag></template></el-table-column><template #empty><div style="padding:20px;color:#aaa;font-size:9px">暂无排片</div></template></el-table></div><div class="table-card"><div class="table-toolbar"><h3>最新订单</h3><router-link to="/cinema-admin/orders" class="section-more">全部订单 <el-icon><ArrowRight /></el-icon></router-link></div><el-table :data="data.orders" size="small"><el-table-column prop="orderNo" label="订单号" width="135"><template #default="{row}"><span class="mono" style="font-size:8px">{{ row.orderNo }}</span></template></el-table-column><el-table-column prop="movieTitle" label="电影" min-width="100" /><el-table-column label="金额" width="75"><template #default="{row}"><b class="text-orange">¥{{ Number(row.amount).toFixed(1) }}</b></template></el-table-column><template #empty><div style="padding:20px;color:#aaa;font-size:9px">暂无订单</div></template></el-table></div></div>
    <section class="cinema-tips mt-24"><div><span>MANAGER'S NOTE</span><h3>今日运营提醒</h3><p>请提前30分钟确认放映设备状态，并及时处理观众的取票核销请求。</p></div><div class="tip-stat"><strong>{{ pendingShows.length }}</strong><span>个排片等待审批</span></div><el-button round @click="router.push('/cinema-admin/showings')">查看排片</el-button></section>
  </div>
